import{_ as p,H as o,f as E,i as t}from"./chunks/framework.BH2BK_3i.js";const A=JSON.parse('{"title":"24五级价值 | 共创洞察：如何做好一次完善的workshop？","description":"","frontmatter":{},"headers":[{"level":2,"title":"企业内部 workshop 的实战方法","slug":"企业内部-workshop-的实战方法","link":"#企业内部-workshop-的实战方法","children":[{"level":3,"title":"步骤 1：确认参会人选","slug":"步骤-1-确认参会人选","link":"#步骤-1-确认参会人选","children":[]},{"level":3,"title":"步骤 2：目标澄清","slug":"步骤-2-目标澄清","link":"#步骤-2-目标澄清","children":[]},{"level":3,"title":"步骤 3：现状分析","slug":"步骤-3-现状分析","link":"#步骤-3-现状分析","children":[]},{"level":3,"title":"步骤 4：策略制定","slug":"步骤-4-策略制定","link":"#步骤-4-策略制定","children":[]}]},{"level":2,"title":"与用户共创的 workshop","slug":"与用户共创的-workshop","link":"#与用户共创的-workshop","children":[]},{"level":2,"title":"今日小结","slug":"今日小结","link":"#今日小结","children":[]},{"level":2,"title":"互动时刻","slug":"互动时刻","link":"#互动时刻","children":[]}],"relativePath":"大厂设计进阶实战课/24五级价值｜共创洞察：如何做好一次完善的workshop？.md","filePath":"大厂设计进阶实战课/24五级价值｜共创洞察：如何做好一次完善的workshop？.md","lastUpdated":1795555085000}'),s={name:"大厂设计进阶实战课/24五级价值｜共创洞察：如何做好一次完善的workshop？.md"};function a(r,e,i,h,l,n){return o(),E("div",null,[...e[0]||(e[0]=[t('<h1 id="_24五级价值-共创洞察-如何做好一次完善的workshop" tabindex="-1">24五级价值 | 共创洞察：如何做好一次完善的workshop？ <a class="header-anchor" href="#_24五级价值-共创洞察-如何做好一次完善的workshop" aria-label="Permalink to &quot;24五级价值 | 共创洞察：如何做好一次完善的workshop？&quot;">​</a></h1><p>你好，我是小乔。</p><p>上节课我们了解了前置设计角色的重要性，也一起学习了被众多企业家力捧的商业模式画布。当我们逐渐把设计师的角色前置，话语权提升，就更有机会参与到业务的规划中。</p><p>在做业务规划时，业务目标、现状问题、解决方案等方面，都需要充分讨论，才能让规划更加全面可行。这个过程，就可以通过 workshop 来进行。有时候业务的负责人会邀请企业内的组织管理专家来主持，或者邀请行业内的咨询公司来做 workshop，但更多的时候，会由业务的决策者们自己组织完成。</p><p>Workshop，也叫参与式工作坊，通过共创的方式达到活动目标。相比于激发灵感的头脑风暴来说，它会更有逻辑性，可落地性也会更强。</p><p>Workshop 的形式，分为企业内部的 workshop 和与用户一起共创的 workshop。通常前者更为严肃，用来制定业务规划，而后者轻松有趣，常常在游戏中获得机会点。这节课，我们就来学习如何做好一次完善的 workshop。这对于我们规划自驱项目，或者和业务方共创项目，都非常实用有效。</p><h2 id="企业内部-workshop-的实战方法" tabindex="-1">企业内部 workshop 的实战方法 <a class="header-anchor" href="#企业内部-workshop-的实战方法" aria-label="Permalink to &quot;企业内部 workshop 的实战方法&quot;">​</a></h2><p>一次完整的企业内部 workshop，主要分为 4 个步骤：确认人选、目标澄清、现状分析和策略制定。接下来我们一步步来讲解。</p><h3 id="步骤-1-确认参会人选" tabindex="-1">步骤 1：确认参会人选 <a class="header-anchor" href="#步骤-1-确认参会人选" aria-label="Permalink to &quot;步骤 1：确认参会人选&quot;">​</a></h3><p>在开展 workshop 之前，我们首先要确认参会人选。具体人选，要根据本次 workshop 的目标而定。比如，我们这次 workshop 是为了确认业务在未来一年的发展规划，因为涉及到整体业务，就要尽量包含所有职能的关键角色，比如运营、产品、设计、开发、算法、战略等职能的负责人。每位负责人代表的视角不同，会更有利于全面规划业务。</p><p>那除了负责人以外，还要加上其他同学吗？是不是人数越多，准确性越高呢？</p><p>其实人数并不是越多越好，人数过多会影响效率和准确性。Workshop 的人数通常以10-20 人为佳。也许有同学希望自己处于一个坦诚清晰、开放透明的企业，希望所有的信息公开透明，由民主决策。但往往全民决策会因为许多缺乏判断力的建议，导致效率极低，甚至决策错误。因此，在参会人选上，以各职能负责人和预备管理者参与为佳，因为他们往往具备更准确的判断力。</p><p>也许有同学会问，小乔姐姐，我不是设计总监，连设计组长都不是，还需要学习这个方法吗？</p><p>其实是需要的，因为 workshop 对于我们制定项目规划也十分有效。比如，我们虽然不需要决策淘宝明年该怎么做，但我们如果自驱了项目，要制定新零售工具或者AR 试穿这个项目的规划，那么对于这个项目有决策权的同事就都应该参加。大家也许都不是团队管理者，但却是这个项目不同职能的负责人。</p><p>所以，当我们学习到新方法后，一定要懂得融会贯通，发挥联想运用能力，找到自己项目上可以实践的机会。不要像个不够智能的机器人一样，非要等到一模一样的情况下再死板照抄、生搬硬套。</p><p>确定人选之后，就要约好时间、地点开展 workshop。通常一个日常项目的讨论只需要半天，但如果是制定某业务明年的规划，类似这样的颗粒度就需要至少 1 天时间。在发布时间和地点的同时，也要将分组名单提前安排好。通常 workshop 会分为 3-5 组不等，分组时要将相同职能、相同级别的同学交错打散，让每一个小组的构成都更为多元。</p><h3 id="步骤-2-目标澄清" tabindex="-1">步骤 2：目标澄清 <a class="header-anchor" href="#步骤-2-目标澄清" aria-label="Permalink to &quot;步骤 2：目标澄清&quot;">​</a></h3><p>当约定时间到来，就可以正式开启 workshop 了。这里，我以一个具体项目作为案例来帮助你理解。</p><p>假设我们现在在负责一个社交产品，这个产品明年会拓展新的海外市场。那么这次的workshop，就是为了制定该产品明年在这个新市场的发展规划。</p><p>开启 worshop 的第一个环节，就是优先对齐明年的项目目标。因为只有对齐目标，才能从目标出发，探讨问题和解决方案。</p><p>通常，业务负责人已经和更高层确认好了业务目标，比如明年在这个新市场的 DAU 渗透率要达到这个国家联网人口的 30%，聊天渗透率要达到 40% 等等。</p><p>对于参会的人员来说，可能并不完全清楚这些目标和指标制定的逻辑，甚至有可能对目标存有质疑，觉得目标过于激进或者过于简单。这个环节，就是为了让在场的各位决策者们都能明白目标制定的原因，并且在讨论中达成共识。</p><p>比如，有人会质疑，Twitter 在这个国家的 DAU 渗透率都只有 20%，我们真的能做到 30%吗？或者，为什么要主推聊天渗透率，不主打其他社交方向，比如帖子发布率、互动率等等？</p><p>业务负责人则需要针对这些问题充分解释清楚，从而让各职能的决策者都能理解公司战略层对于这个业务的要求和目标。如果大家无法对业务目标达成共识，那么也很难在未来凝聚成一股力量，达成共同目标。</p><h3 id="步骤-3-现状分析" tabindex="-1">步骤 3：现状分析 <a class="header-anchor" href="#步骤-3-现状分析" aria-label="Permalink to &quot;步骤 3：现状分析&quot;">​</a></h3><p>在已经对目标达成共识后，就可以针对目标拆分解决方案了。但在思考解决方案之前，需要各职能对业务现状和问题充分理解，才能有针对性地去拆解方案。</p><p>首先，可以让每位参会者写下 5 条以上业务现状，可以是优势也可以是问题，这个数量并不是固定的，只是建议数量。接下来，让每个小组内部充分交流讨论，每个组选出最有共识的现状，不超过 10 条，这个过程有助于大家在发散过后收拢重心。</p><p>每个组挑选出 10 条以内的现状之后，会发现有的是优点，有的是缺点，有的情况在未来会越来越严重，有的问题在未来会逐渐减弱。</p><p>如果我们有 4 个小组，那就有将近 40 个现状。那这些现状，我们又该关注哪些呢？为了更加清晰，我要向你推荐一个可视化工具，我称它为“山河图”。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%8E%82%E8%AE%BE%E8%AE%A1%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/24%25E4%25BA%2594%25E7%25BA%25A7%25E4%25BB%25B7%25E5%2580%25BC/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%8E%82%E8%AE%BE%E8%AE%A1%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/24%25E4%25BA%2594%25E7%25BA%25A7%25E4%25BB%25B7%25E5%2580%25BC/1.png" alt=""></a></p><p>山河图主要由 6 个部分组成：</p><ol><li><p>浮现：这个现状刚刚出现苗头，未来有加重的趋势；</p></li><li><p>上升：这个现状正在逐渐加重，且还会持续加重；</p></li><li><p>顶峰：这个现状已经达到了最大阀值，之后会逐渐减弱；</p></li><li><p>下行：这个现状已经在逐渐减轻，且未来还会持续减轻；</p></li><li><p>静止：这个现状目前已经发展到尾声，之后将不再发生巨大变化；</p></li><li><p>暗流：暂且难以判断这个现状的发展趋势，也许会蓬勃发展，也许会销声匿迹。</p></li></ol><p>根据这 6 个部分，不同小组就可以将自己组内选出的 10 条现状贴到相应的位置，问题风险相关的现状可以换一个颜色标出，引起大家的共同关注。这样贴完之后就会一目了然。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%8E%82%E8%AE%BE%E8%AE%A1%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/24%25E4%25BA%2594%25E7%25BA%25A7%25E4%25BB%25B7%25E5%2580%25BC/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%8E%82%E8%AE%BE%E8%AE%A1%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/24%25E4%25BA%2594%25E7%25BA%25A7%25E4%25BB%25B7%25E5%2580%25BC/2.png" alt=""></a></p><p>我们举例来说，最近运营 leader 离职了，运营活动质量显著下降，互动数据不佳，并且短期内没有那么容易招聘到一个满意的新 leader，那么这条现状就会放在“上升”部分；再来，业务之前一直在做陌生人方向，最近终于确定不再以陌生人社交为主了，那这条就在“静止”部分。</p><p>通过“山河图”，大家可以很清晰地明白哪些情况在越来越好，哪些情况在越来越糟糕。以上图为例，我们看到“下行”部分的橙色内容最多，这其实是个好现象，说明各种问题正在逐渐消失，业务也在越来越好。</p><h3 id="步骤-4-策略制定" tabindex="-1">步骤 4：策略制定 <a class="header-anchor" href="#步骤-4-策略制定" aria-label="Permalink to &quot;步骤 4：策略制定&quot;">​</a></h3><p>在达成目标共识、充分理解现状过后，就到了最为激动人心的步骤：策略制定。</p><p>和上一步骤同理，组内的每个成员需要写下 5 条以上解决方案，以克服问题，达到业务目标和指标。接下来，组内充分讨论，互相激发和优化各自的解决方案，并将相似的解决方案进行整合。</p><p>每个组各自讨论完毕后，就到各组一起交流的时候了。每个小组可以轮流发言，并将各组的解决方案贴在共创文档里或者白板上，当听到同一类型的解决方案时，就归纳整合在一起。每个小组都分享完毕后，我们就会得到一张分好类的大图。</p><p>如下图所示，一共归纳出 9 大类解决方案，下面是每个组提出的具体方案，形成了解决方案矩阵。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%8E%82%E8%AE%BE%E8%AE%A1%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/24%25E4%25BA%2594%25E7%25BA%25A7%25E4%25BB%25B7%25E5%2580%25BC/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%8E%82%E8%AE%BE%E8%AE%A1%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/24%25E4%25BA%2594%25E7%25BA%25A7%25E4%25BB%25B7%25E5%2580%25BC/3.png" alt=""></a></p><p>接下来，针对这些解决方案，就可以排列出优先级。还记得我们曾经讲过如何排列需求的优先级吗？这里也是同理，根据业务目标，会从重要性、紧急度、可控性、成本、营收、创新性等维度进行打分，再综合计算每个大类的分数，分数高的则优先处理。如果这些维度之间也有优先级之分，那在计算总和时，还需要在每个维度上再乘以权重。</p><p>在这里，我想向你介绍另一种排列优先级的方法，就是投票。投票的方法，一般不建议用在工作中，因为当人数很多时，真理不一定在多数人手上。为什么我们在这里可以投票决策呢？这其实又一次验证了我们开设 workshop，需要有决策能力和强判断力的人员参加，因为这样的投票才是有效的、准确率高的。</p><p>比如，我们先要求每个人对重要性投票，重要性就是有效程度，通过这个解决方案可以有效达成目标，那这个方案就是重要的。我们让每位参会者投 3 个最能达成目标的选项，当然，这个数字也不是固定的，可根据方案归类的总数量进行调整。</p><p>我们回到步骤 2 中海外社交项目的案例来继续讲解。因为这个业务在新国家入局并不是一件容易的事情，会受到国家政策、当地运营商的配合程度、当地团队搭建难度、对当地的了解情况等各方面制约，因此，可控性也是重要的衡量条件。当对可控性也投票之后，就可以得到以下数字。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%8E%82%E8%AE%BE%E8%AE%A1%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/24%25E4%25BA%2594%25E7%25BA%25A7%25E4%25BB%25B7%25E5%2580%25BC/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%8E%82%E8%AE%BE%E8%AE%A1%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/24%25E4%25BA%2594%25E7%25BA%25A7%25E4%25BB%25B7%25E5%2580%25BC/4.png" alt=""></a></p><p>如果只有两个维度，没有更多维度要考虑，就可以通过十字象限法进行定位。根据参会者在重要性和可控性上的打分，把各项解决方案画在十字象限中。由下图可知，优先应当关注右上角这个象限的解决方案，接着关注左上角和右下角，最后再关注左下角。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%8E%82%E8%AE%BE%E8%AE%A1%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/24%25E4%25BA%2594%25E7%25BA%25A7%25E4%25BB%25B7%25E5%2580%25BC/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%8E%82%E8%AE%BE%E8%AE%A1%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/24%25E4%25BA%2594%25E7%25BA%25A7%25E4%25BB%25B7%25E5%2580%25BC/5.png" alt=""></a></p><p>到此为止，全部参会人员就共创完成了本次 workshop，且在整个过程中，都在不断拉齐认知，最终达成了共识。</p><h2 id="与用户共创的-workshop" tabindex="-1">与用户共创的 workshop <a class="header-anchor" href="#与用户共创的-workshop" aria-label="Permalink to &quot;与用户共创的 workshop&quot;">​</a></h2><p>探讨完如何开展企业内部的 workshop 后，我们再来讲讲与用户共创的 workshop 方法。</p><p>如果我们做工作坊的目的并不是产出严肃的业务规划，而是想拉着用户一起共创，根据某个命题收集一些有效洞察，并让用户感受到我们的企业文化，那就可以采用还原场景、实践探索的方式来开展 workshop。</p><p>比如，车企可以和用户一起探讨车友会的服务，消费升级型业务可以和用户探讨人们在收入不同时消费结构的变化，母婴业务可以和宝爸宝妈们一起探讨照顾儿童的诉求等等。这样的workshop 通常会非常轻松有趣，在愉快的共创氛围中达到目的。</p><p>整个流程和我们上文讲的 4 个步骤一致。首先是确认参会人选。在真实用户中，筛选一些符合本次探讨命题的用户，向他们发出邀请，同时表明本次 workshop 的目的，通常这样的workshop 也会配有茶歇和可带走的小礼品，吸引用户参与。</p><p>第 2 步是目标澄清。在 workshop 开场前做好分组，让每个小组的参会者围坐在一起。开始后，主持人首先表明本次活动的目的，共同探索一个命题，并且表达企业对于用户观点的重视，欢迎用户共创，这也是一次宣传企业文化的好机会。</p><p>第 3 步是分析现状。可以给每个组发一些帮助探索的道具，比如大张的图纸、彩色笔、橡皮泥、积木、乐高等，鼓励参会者使用这些道具还原真实场景。</p><p>举个例子，在咨询行业时，我们曾组织过一次对外的行业分享大会，以消费升级为主题。其中有个环节就是 workshop，让听众真实地感受消费升级对自己的消费结构产生的变化。</p><p>当时我们的道具就是示意用的纸钱，分发给每个组，然后在大纸上画好衣食住行、投资、理财、教育、娱乐等各方面的分区。当月薪分别为 3 千元，3 万元，30 万元时，每个小组共同讨论如何分配消费，将多少钱放置在哪个区域，从而观察消费升级对消费结构的分配变化。</p><p>第 4 步是策略制定。前面的实践过程，会引发出大家的一些思考和问题，也会有一些明确的用户需求被发现，此时就可以一起探索解决方案。这个过程和企业内部 workshop 的方法一致。</p><p>比如，对车友来说，熟悉的都是同一个城市的车友，但如果去另一个城市，又如何与当地的车友链接，获得在新城市旅游的帮助呢？对多项解决方案的有效性、车友意愿度等维度打分后，也许就会得出，可以在车友会的 App 中提供发出旅行单和接收旅行单的功能，让车友们链接。</p><h2 id="今日小结" tabindex="-1">今日小结 <a class="header-anchor" href="#今日小结" aria-label="Permalink to &quot;今日小结&quot;">​</a></h2><p>今天，我们一起学习了开展 workshop 的全流程。企业内部的 workshop 主要有两个作用，一个是完成本次 workshop 讨论的议题目标，另一个是让各职能的决策者都达成共识；与用户共创的 workshop 也有两个作用，一个是通过用户发现机会点，另一个是向用户传播企业文化。</p><p>开展 workshop 分为 4 个步骤，分别是：确认参会人选、目标澄清、现状分析和策略制定。这是一个循序渐进的过程，先将目标拉齐后，才能探讨针对目标的现状、问题，进而讨论解决方案。我们也在这节课学习了两种判定优先级的方式，一种是曾经学过的 matrix 打分法，另一种就是这节课讲解的投票法。</p><p>从目标出发，拆分解决方案，这个过程，你是否觉得十分熟悉？</p><p>没错，这个过程像极了我们曾经讲过的项目复盘方法和四步拆解法。</p><p>你会发现，古今中外的各种推导分析方法，不管是经典的方法论还是根据时代变迁总结的新创方法论，底层逻辑都是相似的。因此，具体的方法会根据时代发展不断优化，但更重要的是，你能理解从目标到解决方案的拆分逻辑，说不定在未来，你还可以新创出更适合行业的方法论。</p><h2 id="互动时刻" tabindex="-1">互动时刻 <a class="header-anchor" href="#互动时刻" aria-label="Permalink to &quot;互动时刻&quot;">​</a></h2><p>回顾你过往的工作经历，是否参加过人员众多，七嘴八舌讨论，却无法收拢结论的低效会议？学完这节课的你，打算怎么做呢？</p><p>欢迎把你的经历和思考在留言区分享出来，与我和其他同学一起探讨。我们建了一个读者交流群，欢迎你的加入！如果你觉得有所收获，也欢迎把文章分享给你的朋友一起学习。我们下节课见。</p>',70)])])}const k=p(s,[["render",a]]);export{A as __pageData,k as default};
